def _run_expression_cycle(self, codex, telemetry_snapshot):
    expr = codex.get('genomic_expression', {})
    rules = expr.get('rules', [])
    for rule in rules:
        if self._matches(rule['when'], telemetry_snapshot):
            self._emit_expression_plan(rule['then'])

def _emit_expression_plan(self, then_block):
    self.ns_emit_msg(
        dst_plane='P1',
        channel='shadow_fairy',
        opcode='PLAN_EXPRESSION',
        payload=then_block,
    )
